const icon=name=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+(paths[name]||paths.box)+'"/></svg>';
const tabs=[['home','首页'],['inbound','入库'],['outbound','出库'],['mine','我的']];
const escape=value=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
let current=location.hash.slice(1)||'home',state=new URLSearchParams(location.search).get('state')||'normal',toastTimer;
if(!tabs.some(t=>t[0]===current))current='home';
document.querySelector('#review-state').value=state;
const money=n=>Number(n).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const input=(label,value,extra='',type='text')=>'<label class="field '+(extra.includes('wide')?'wide':'')+'"><span>'+label+'</span><input type="'+type+'" value="'+escape(value)+'" '+extra.replace('wide','')+'></label>';
const header=(title,sub,tail='')=>'<header class="page-header"><div><h1>'+title+'</h1><p>'+sub+'</p></div>'+tail+'</header>';
function notify(text){const el=document.querySelector('#toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,2400)}
let confirmAction=null; function modal(title,description,onConfirm=null){confirmAction=onConfirm;document.querySelector('#confirm-dialog').hidden=!onConfirm;document.querySelector('#close-dialog').textContent=onConfirm?'取消':'知道了';document.querySelector('#dialog-content').innerHTML='<h2>'+escape(title)+'</h2><p>'+escape(description)+'</p>';document.querySelector('#preview-dialog').showModal()}
function stateView(){if(state==='normal')return '';if(state==='loading')return '<section aria-label="正在加载" aria-busy="true"><div class="skeleton"></div><div class="skeleton"></div></section>';const error=state==='error';return '<section class="card empty" '+(error?'role="alert"':'')+'><div class="icon-tile">'+icon(error?'refresh':'box')+'</div><h2>'+(error?'暂时无法加载':'从第一笔业务开始')+'</h2><p>'+(error?'当前离线，恢复后可重新加载。':'记录每一次流转，让库存清楚有序。')+'</p><button class="button primary" data-reset>'+(error?'重新加载':'查看录单样稿')+'</button></section>'}
function home(){const metrics=[['box','商品种类','24','种'],['list','库存总量','86,420','张'],['money','库存总值','48,632.00','元 · 成本价'],['warning','预警商品','3','种']];const shortcuts=[['inbound','入库','inbound'],['outbound','出库','outbound'],['box','库存'],['list','商品'],['users','客户'],['truck','供应商'],['calendar','订单'],['list','记录'],['money','账本'],['calculator','纸箱计算'],['calculator','瓦楞计算']];return '<section class="hero"><div class="hero-top"><div><h1>曙光库存</h1><p>9 月 25 日 · 星期五</p></div><span class="hero-badge">每一笔，都清楚</span></div><div class="hero-stats"><div><small>今日入库</small><strong>6,800</strong><small>张 · ¥3,740.00</small></div><div><small>今日出库</small><strong>4,200</strong><small>张 · ¥4,032.00</small></div><div><small>库存预警</small><strong>3</strong><small>种商品需补货</small></div></div></section><section class="section"><div class="section-title"><h2>经营概览</h2><span class="caption">数据一目了然</span></div><div class="overview">'+metrics.map((m,i)=>'<div class="card metric"><div class="metric-top">'+icon(m[0])+m[1]+'</div><strong class="'+(i===3?'warning-text':'')+'">'+m[2]+'</strong><small>'+m[3]+'</small></div>').join('')+'</div></section><section class="section card"><div class="section-title"><h2>库存流转</h2><div class="segment" aria-label="趋势时间范围"><button aria-pressed="true" data-period="7">7 天</button><button aria-pressed="false" data-period="30">30 天</button></div></div><div class="legend"><span><i class="dot"></i>入库</span><span><i class="dot light"></i>出库</span><span>单位：千张</span></div><svg class="chart" viewBox="0 0 330 160" role="img" aria-label="示例近七天入库与出库数量趋势"><path class="grid" d="M28 16h290M28 70h290M28 124h290"/><text x="0" y="20">10</text><text x="7" y="74">5</text><text x="7" y="128">0</text><path class="series-b" d="M28 98 76 80 124 92 172 48 220 63 268 87 316 79"/><path class="series-a" d="M28 78 76 54 124 72 172 27 220 42 268 62 316 50"/><text x="28" y="151">09/19</text><text x="149" y="151">09/22</text><text x="279" y="151">09/25</text></svg></section><section class="section"><div class="section-title"><h2>常用功能</h2></div><div class="shortcuts">'+shortcuts.map(s=>'<button class="shortcut" '+(s[2]?'data-tab="'+s[2]+'"':'data-preview="'+s[1]+'"')+'><span class="icon-tile">'+icon(s[0])+'</span>'+s[1]+'</button>').join('')+'</div></section><section class="section"><div class="section-title"><h2>今日待办</h2><button class="link" data-preview="待办中心">查看全部 →</button></div><div class="card"><div class="todo"><div><p class="row-title">2 笔订单待送货</p><p class="row-sub">最早交期 · 今天</p></div><span class="badge">待处理</span></div><div class="todo"><div><p class="row-title">3 种商品库存偏低</p><p class="row-sub">三层 B 楞纸板 · 余 120 张</p></div><span class="badge warning">补货提醒</span></div></div></section>'}
let lineCount=1;
function purchaseLine(i){return '<article class="card purchase-line"><div class="line-head"><h3>明细 '+i+'</h3><button class="link" data-delete-line>删除</button></div><div class="fields">'+input('规格 / 楞型','1550×705 / A','wide data-spec list="specifications"')+input('订货数量 · 张','2000','min="1"','number')+input('单价 · 元/张','0.55','data-price min="0" step="0.01"','number')+input('实际送货 · 张','2000','data-delivered min="1"','number')+'<label class="field"><span>克重 · g/m²</span><input value="120" inputmode="decimal"></label></div><div class="line-footer"><span data-area>面积 2,185.50 m²</span><strong data-line-total>¥1,100.00</strong></div></article>'}
function inbound(){return header('纸板入库','一张送货单，库存与应付同步记录','<span class="draft-chip">新建单据</span>')+'<section class="card"><h2>基础信息</h2><div class="fields">'+input('入库日期','2026-09-25','','date')+input('单据编号','RK-0925-001','readonly')+'<label class="field wide"><span>供应商 <span class="required">*</span></span><select><option>示例 · 青禾纸业</option><option>示例 · 云杉包装</option></select></label>'+input('司机','陈师傅')+input('车号','浙 A·12345')+input('运费 · 元','80.00','min="0" step="0.01"','number')+'<label class="field"><span>付款方式</span><select><option>挂账</option><option>现结</option></select></label></div></section><section class="section"><div class="section-title"><h2>入库明细</h2><span class="caption">按实际送货数入库</span></div><div id="purchase-lines">'+purchaseLine(1)+'</div><button class="button full add-line" data-add-line>'+icon('plus')+'添加一行</button></section><section class="section card">'+input('备注','送到仓库后请联系收货','wide')+'<label class="check-line"><input type="checkbox" checked>入库后自动创建打印任务</label></section><datalist id="specifications"><option value="1550×705 / A"><option value="1200×800 / B"></datalist>'}
function outbound(){return header('销售出库','选好商品，清楚记录每一次交付','<button class="icon-button" data-preview="从订单带入" aria-label="从订单带入">'+icon('list')+'</button>')+'<section class="card"><button class="product-choice" data-preview="选择商品"><span class="product-art">'+icon('box')+'</span><span class="grow"><strong>三层 A 楞纸板</strong><span class="row-sub" style="display:block">1550×705 · 牛卡 / 瓦楞</span><span class="badge">可用库存 8,640 张</span></span>'+icon('chevron')+'</button></section><section class="section card"><h2>出库信息</h2><div class="fields">'+input('规格','1550×705','list="out-spec"')+input('材质','牛卡 / 瓦楞','list="out-material"')+'<label class="field"><span>计量单位</span><select>'+['张','件','箱','个','千克','平方米','令','卷'].map(x=>'<option>'+x+'</option>').join('')+'</select></label>'+input('单价 · 元/张','0.96','id="sale-price" min="0" step="0.01"','number')+'<label class="field wide"><span>出库数量</span><span class="stepper"><button type="button" data-step="-1" aria-label="减少数量">−</button><input id="sale-quantity" type="number" value="1200" min="1" aria-label="出库数量"><button type="button" data-step="1" aria-label="增加数量">+</button></span></label></div><div class="amount-row"><span>本单金额</span><strong id="sale-total">¥1,152.00</strong></div><div class="fields"><label class="field wide"><span>客户 <span class="required">*</span></span><select><option>示例 · 松林包装</option><option>示例 · 青木纸品</option></select></label>'+input('出库日期','2026-09-25','','date')+input('操作人','经办人')+input('备注','请送至东门仓库','wide')+'</div><label class="check-line"><input type="checkbox" checked>保存后打印送货单</label></section><section class="section"><div class="section-title"><h2>最近出库</h2><button class="link" data-preview="出库记录">全部记录 →</button></div><div class="card todo"><div><p class="row-title">三层 B 楞纸板</p><p class="row-sub">800 张 × ¥0.85 · 今天 10:32</p></div><strong>¥680.00</strong></div></section><datalist id="out-spec"><option value="1550×705"><option value="1200×800"></datalist><datalist id="out-material"><option value="牛卡 / 瓦楞"><option value="白卡 / 瓦楞"></datalist>'}
function mine(){const groups=[['业务工具',[['print','打印中心','模板、设备与打印任务'],['settings','公司与单据设置','公司抬头、单号与业务偏好'],['calculator','计算工具','纸箱用料与瓦楞卷径']]],['数据与备份',[['shield','备份与恢复','保留每一笔业务的安全副本'],['download','导出与导入','完整数据导出、预览后导入']]],['系统',[['refresh','检查更新','当前版本 · 样稿预览'],['download','安装与下载','获取各平台安装包'],['chart','诊断与数据健康','连接、同步与数据一致性'],['sun','关于曙光','把复杂留给系统，把清楚留给你']]]];return '<section class="profile"><div class="profile-mark">'+icon('sun')+'</div><h1>曙光库存</h1><p>纸箱与纸板生意，井井有条。</p></section>'+groups.map(g=>'<section class="section"><div class="section-title"><h2>'+g[0]+'</h2></div><div class="card menu-group">'+g[1].map(m=>'<button class="menu-item" data-preview="'+m[1]+'"><span class="icon-tile">'+icon(m[0])+'</span><span class="grow"><span class="row-title">'+m[1]+'</span><span class="row-sub" style="display:block">'+m[2]+'</span></span>'+icon('chevron')+'</button>').join('')+'</div></section>').join('')+'<p class="footer-note">曙光 · 让每一次流转都有迹可循</p>'}
function updateTotals(){if(current==='outbound'){const q=Number(document.querySelector('#sale-quantity')?.value),p=Number(document.querySelector('#sale-price')?.value);if(document.querySelector('#sale-total'))document.querySelector('#sale-total').textContent='¥'+money(q*p);if(document.querySelector('#fixed-total'))document.querySelector('#fixed-total').textContent='¥'+money(q*p)}if(current==='inbound'){let total=0,area=0;document.querySelectorAll('.purchase-line').forEach(line=>{const q=Number(line.querySelector('[data-delivered]').value),p=Number(line.querySelector('[data-price]').value);const spec=line.querySelector('[data-spec]');const dims=spec.value.match(/^ *([0-9]+(?:[.][0-9]+)?) *[×xX*] *([0-9]+(?:[.][0-9]+)?)(?: *[/].*)? *$/);const valid=dims&&Number(dims[1])>0&&Number(dims[2])>0;spec.setAttribute('aria-invalid',String(!valid));const lineArea=valid?q*Number(dims[1])*Number(dims[2])/1000000:0;total+=q*p;area+=lineArea;line.querySelector('[data-line-total]').textContent='¥'+money(q*p);line.querySelector('[data-area]').textContent=valid?'面积 '+money(lineArea)+' m²':'请输入有效长×宽（mm）'});document.querySelector('#fixed-total').textContent='¥'+money(total);document.querySelector('#fixed-sub').textContent=money(area)+' m² · 货款合计（不含运费）'}}
function render(){const main=document.querySelector('#screen');main.className=(state==='normal'&&['inbound','outbound'].includes(current))?'has-action':'';main.innerHTML=state==='normal'?({home:()=>home()+homeDetails(),inbound,outbound,mine}[current]()) : header(tabs.find(x=>x[0]===current)[1],'曙光库存')+stateView();document.querySelector('#tabs').innerHTML=tabs.map(t=>'<button data-tab="'+t[0]+'" '+(current===t[0]?'aria-current="page"':'')+'>'+icon(t[0])+t[1]+'</button>').join('');document.querySelector('#action').innerHTML=main.className?'<div class="total"><small id="fixed-sub">'+(current==='inbound'?'货款合计（不含运费）':'本单应收 · 元')+'</small><strong id="fixed-total">¥0.00</strong></div><button class="button primary" data-submit>确认'+(current==='inbound'?'入库':'出库')+'</button>':'';if(main.className)updateTotals()}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.tab){current=b.dataset.tab;location.hash=current;render();scrollTo(0,0)}if(b.hasAttribute('data-reset')){state='normal';document.querySelector('#review-state').value=state;render()}if(b.dataset.preview)modal(b.dataset.preview,'这是第一阶段视觉样稿。此入口展示信息架构，完整功能将在样稿确认后实现。');if(b.hasAttribute('data-add-line')){document.querySelector('#purchase-lines').insertAdjacentHTML('beforeend',purchaseLine(++lineCount));updateTotals()}if(b.hasAttribute('data-delete-line')){if(document.querySelectorAll('.purchase-line').length===1){notify('至少保留一行明细');return}const line=b.closest('.purchase-line');modal('删除这行明细？','此操作仅删除样稿中的这一行，可取消返回。',()=>{line.remove();updateTotals()})}if(b.dataset.step){const el=document.querySelector('#sale-quantity');el.value=Math.max(1,Number(el.value)+Number(b.dataset.step));updateTotals()}if(b.dataset.period){document.querySelectorAll('[data-period]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const monthly=b.dataset.period==='30';document.querySelector('.series-a').setAttribute('d',monthly?'M28 92 76 74 124 81 172 42 220 54 268 22 316 40':'M28 78 76 54 124 72 172 27 220 42 268 62 316 50');document.querySelector('.chart').setAttribute('aria-label',monthly?'示例近三十天入库与出库数量趋势':'示例近七天入库与出库数量趋势');document.querySelector('.series-b').setAttribute('d',monthly?'M28 109 76 85 124 91 172 66 220 76 268 52 316 63':'M28 98 76 80 124 92 172 48 220 63 268 87 316 79');document.querySelector('.chart text:nth-last-child(3)').textContent=monthly?'08/27':'09/19';document.querySelector('.chart text:nth-last-child(2)').textContent=monthly?'09/10':'09/22'}if(b.hasAttribute('data-submit')){updateTotals();let invalid=Boolean(document.querySelector('[data-spec][aria-invalid=true]'));document.querySelectorAll('input[type=number]').forEach(x=>{const bad=!x.checkValidity()||x.value==='';x.setAttribute('aria-invalid',String(bad));invalid=invalid||bad});if(invalid){notify('请检查规格、数量和单价格式');return}b.disabled=true;b.textContent='正在保存…';setTimeout(()=>{b.disabled=false;b.textContent='确认'+(current==='inbound'?'入库':'出库');notify('样稿保存反馈演示 · 未提交任何业务数据')},650)}});
document.addEventListener('input',()=>{if(state==='normal'&&['inbound','outbound'].includes(current))updateTotals()});document.querySelector('#review-state').addEventListener('change',e=>{state=e.target.value;render()});document.querySelector('#close-dialog').onclick=()=>document.querySelector('#preview-dialog').close();document.querySelector('#confirm-dialog').onclick=()=>{const action=confirmAction;confirmAction=null;document.querySelector('#preview-dialog').close();action?.()};window.addEventListener('hashchange',()=>{if(tabs.some(x=>x[0]===location.hash.slice(1))){current=location.hash.slice(1);render()}});render();
